using Mono.Cecil;

public static class LightingFireContractChecks
{
    public static (int Checks,int Failures) Run(IReadOnlyDictionary<string,TypeDefinition> types,AssemblyDefinition mod)
    {
        int checks=0,failures=0;
        void Check(string name,bool good){checks++;if(!good)failures++;Console.WriteLine((good?"PASS ":"FAIL ")+"lighting/fire "+name);}
        bool Fields(string name,params(string Name,string Type)[] fields)=>types.TryGetValue(name,out var type)&&fields.All(expected=>type.Fields.Any(field=>field.Name==expected.Name&&field.FieldType.FullName==expected.Type&&!field.IsStatic));
        MethodDefinition? Native(string name,string method)=>types.TryGetValue(name,out var type)?type.Methods.FirstOrDefault(value=>value.Name==method&&value.HasBody):null;
        bool Calls(MethodDefinition? body,string type,string name)=>body?.Body.Instructions.Any(instruction=>instruction.Operand is MethodReference method&&method.DeclaringType.GetElementType().FullName==type&&method.Name==name)==true;
        bool Read(MethodDefinition? body,string type,string name)=>body?.Body.Instructions.Any(instruction=>instruction.Operand is FieldReference field&&field.DeclaringType.GetElementType().FullName==type&&field.Name==name)==true;
        Check("native lamp arrays and exact owning aircraft",Fields("NavLights",("navLights","NavLights/NavLight[]"),("aircraft","Aircraft")));
        Check("native individual lamp presentation and control mode",Fields("NavLights/NavLight",("renderer","UnityEngine.Renderer"),("objects","UnityEngine.GameObject[]"),("litMaterial","UnityEngine.Material"),("baseMaterial","UnityEngine.Material"),("part","UnitPart"),("gear","LandingGear"),("controlState","NavLights/ControlledState"),("isOn","System.Boolean")));
        Check("native light control enum preserves explicit ForceOn",types.TryGetValue("NavLights/ControlledState",out var controls)&&new[]{("Never",0),("Auto",1),("ForceOn",2)}.All(expected=>controls.Fields.Any(field=>field.Name==expected.Item1&&field.HasConstant&&Convert.ToInt32(field.Constant)==expected.Item2)));
        Check("native gear state enum matches auto light policy",types.TryGetValue("LandingGear/GearState",out var gear)&&new[]{("LockedRetracted",1),("LockedExtended",2),("Retracting",3),("Extending",4)}.All(expected=>gear.Fields.Any(field=>field.Name==expected.Item1&&field.HasConstant&&Convert.ToInt32(field.Constant)==expected.Item2)));
        Check("native lamp gear transitions call toggle",Calls(Native("NavLights/NavLight","NavLight_OnSetGear"),"NavLights/NavLight","Toggle"));
        Check("native lamp override has exact aircraft owner and boolean toggle",Fields("NavLights/NavLight",("aircraft","Aircraft"))&&types.TryGetValue("NavLights/NavLight",out var nativeLamp)&&nativeLamp.Methods.Count(method=>method.Name=="Toggle"&&!method.IsStatic&&method.ReturnType.FullName=="System.Void"&&method.Parameters.Select(parameter=>parameter.ParameterType.FullName).SequenceEqual(new[]{"System.Boolean"}))==1);
        Check("native broken gear detaches hinge rather than changing component meaning",Fields("LandingGear",("attachedPart","AeroPart"),("gearHinge","UnityEngine.Transform"))&&Calls(Native("LandingGear","BreakWheel"),"UnityEngine.Transform","SetParent"));
        Check("native fuel fire instance and prefab references",Fields("FuelTank",("part","UnitPart"),("fireEffect","UnityEngine.GameObject"),("fireEffectSpawn","UnityEngine.GameObject"),("fireballSpawn","UnityEngine.GameObject"),("leakSystem","UnityEngine.ParticleSystem")));
        Check("native damage fire timing motion and particle references",Fields("DamageParticles",("time","System.Single"),("speed","System.Single"),("systemBehaviours","DamageParticles/SystemBehaviour[]"),("fireLight","UnityEngine.Light"),("rb","UnityEngine.Rigidbody"),("unitPart","UnitPart"),("detached","System.Boolean"),("fireDamage","System.Single")));
        Check("native particle behavior observable fade and speed response",Fields("DamageParticles/SystemBehaviour",("system","UnityEngine.ParticleSystem"),("fadeOpacity","System.Single"),("baseRate","System.Single"),("increaseRateWithSpeed","System.Single"),("reduceOpacityWithSpeed","System.Single"),("reduceLifeWithSpeed","System.Single"),("lowerLifetime","System.Single"),("upperLifetime","System.Single"),("lowerColor","UnityEngine.Color"),("upperColor","UnityEngine.Color")));
        Check("native damage awake schedules detach timer on kinematic fallback",Calls(Native("DamageParticles","Awake"),"DamageParticles","DetachTimer")&&Native("DamageParticles","DetachTimer")?.ReturnType.FullName=="Cysharp.Threading.Tasks.UniTask");
        Check("native culling reparents and stops persistent fire presentation",Calls(Native("DamageParticles","ParentObjectCulled"),"UnityEngine.Transform","SetParent")&&Calls(Native("DamageParticles","ParentObjectCulled"),"DamageParticles/SystemBehaviour","Stop"));
        var compiled=AllTypes(mod.MainModule.Types).ToDictionary(type=>type.FullName);
        MethodDefinition? Body(string name,string method,string? parameter=null)=>compiled.TryGetValue(name,out var type)?type.Methods.FirstOrDefault(value=>value.Name==method&&value.HasBody&&(parameter==null||value.Parameters.Any(p=>p.ParameterType.FullName==parameter))):null;
        const string recorder="ReplayMod.Core.Recorder",controller="ReplayMod.Core.UnitController",light="ReplayMod.Core.ReplayAircraftLights",fire="ReplayMod.Core.ReplayFuelFlameVisual",legacy="ReplayMod.Core.ReplayDamageParticleMotion",flameEvent="ReplayMod.Events.ConcreteEvents.FuelFlameStateEvent",flameState="ReplayMod.Core.ReplayFuelFlameState",seek="ReplayMod.Core.ReplaySeekState";
        Check("compiled lamp capture observes actual objects and control state",Read(Body(light,"Capture"),"NavLights/NavLight","controlState")&&Read(Body(light,"Capture"),"NavLights/NavLight","objects")&&Calls(Body(recorder,"RecordAircraftLights"),light,"Capture"));
        Check("compiled gear-aware lamp refresh avoids native simulation enabled flag",Calls(Body(light,"Apply"),"ReplayMod.Data.AircraftLightingPolicy","Resolve")&&Read(Body(light,"Apply"),"Aircraft","gearState")&&!Calls(Body(light,"Apply"),"UnityEngine.Behaviour","get_enabled"));
        Check("compiled lamp snapshots and overrides refresh during replay",Calls(Body(controller,"RefreshAircraftVisualsLate"),controller,"RefreshReplayLights")&&Calls(Body(controller,"ClearPlaybackLights"),"System.Collections.Generic.Dictionary`2","Clear")&&Calls(Body(recorder,"LateUpdate"),recorder,"RecordAircraftLights"));
        var togglePatch=Body("ReplayMod.Patches.ReplayAircraftLightOverridePatch","AfterToggle");
        Check("native lamp callbacks reapply replay overrides without recursive toggles",Calls(togglePatch,"ReplayMod.Core.ReplayRuntime","get_IsPlayback")&&Calls(togglePatch,"ReplayMod.Core.Player","RefreshPlaybackLights")&&Calls(Body(controller,"RefreshReplayLightsFor"),controller,"FindActor")&&Calls(Body(controller,"RefreshReplayLightsFor"),controller,"ApplyPlaybackLights")&&!Calls(Body(light,"Apply"),"NavLights/NavLight","Toggle"));
        Check("compiled native source captures emission fade observed light and attachment",Read(Body(recorder,"CaptureFuelFlame"),"DamageParticles/SystemBehaviour","fadeOpacity")&&Read(Body(recorder,"CaptureFuelFlame"),"DamageParticles","speed")&&Calls(Body(recorder,"CaptureFuelFlame"),"UnityEngine.ParticleSystem","get_isEmitting")&&Calls(Body(recorder,"CaptureFuelFlame"),"UnityEngine.Light","get_intensity")&&Calls(Body(recorder,"CaptureFuelFlame"),recorder,"IsTracked"));
        Check("compiled fire source lifecycle retains effects beyond actor lookup removal",Calls(Body(recorder,"LateUpdate"),recorder,"CaptureFuelFlamesLate")&&Calls(Body(recorder,"ForgetFuelFlameUnit"),"System.Collections.Generic.Dictionary`2","Remove")&&!Calls(Body(recorder,"ForgetFuelFlameUnit"),recorder,"EndFuelFlame")&&Calls(Body(recorder,"ClearRecordingVfx"),recorder,"ClearRecordingFuelFlames"));
        var ctor=Body(fire,".ctor");var instructions=ctor?.Body.Instructions??new Mono.Collections.Generic.Collection<Mono.Cecil.Cil.Instruction>();
        Check("compiled controlled fire prefab registers before activation and disables damage script",Calls(ctor,"UnityEngine.GameObject","SetActive")&&Calls(ctor,"UnityEngine.Object","Instantiate")&&Calls(ctor,"System.Collections.Generic.HashSet`1","Add")&&Calls(ctor,"UnityEngine.Behaviour","set_enabled")&&Read(ctor,"DamageParticles","systemBehaviours"));
        var visualBodies=compiled[fire].Methods.Where(method=>method.HasBody).ToArray();
        Check("compiled fire view uses observed fade and light with no damage or ignition simulation",visualBodies.All(method=>method.Body.Instructions.All(instruction=>instruction.Operand is not MethodReference call||call.Name is not("TakeDamage" or "FuelTankFire" or "IgnitionEffects" or "UpdateStatus")))&&Calls(Body(fire,"Apply"),"UnityEngine.Light","set_intensity")&&Calls(Body(fire,"Apply"),"UnityEngine.ParticleSystem","Stop"));
        var apply=Body(fire,"Apply");var applyCalls=apply?.Body.Instructions.Where(instruction=>instruction.Operand is MethodReference).Select(instruction=>(MethodReference)instruction.Operand).ToArray()??Array.Empty<MethodReference>();
        int color=Array.FindIndex(applyCalls,method=>method.Name=="set_startColor"),simulate=Array.FindIndex(applyCalls,method=>method.Name=="Simulate");
        Check("compiled seek warmup applies recorded colour before simulation and guards stopped effects",color>=0&&simulate>color&&Calls(apply,"ReplayMod.Data.FuelFlameWarmPolicy","Duration"));
        Check("compiled controlled native awake and cull are exact owned guards",Calls(Body("ReplayMod.Patches.ReplayRecordedFuelFlameAwakePatch","Prefix"),fire,"IsControlled")&&Calls(Body("ReplayMod.Patches.ReplayRecordedFuelFlameCullPatch","Prefix"),fire,"IsControlled"));
        Check("compiled kinematic native fallback detach timer is canceled only for owned effects",Calls(Body("ReplayMod.Patches.ReplayDamageParticleDetachTimerPatch","Prefix"),legacy,"CanOwn")&&Calls(Body(legacy,"CanOwn"),"ReplayMod.Core.ReplayVfxPlayback","IsOwnedActor")&&Calls(Body(legacy,"CanOwn"),"ReplayMod.Core.ReplayRuntime","get_IsPlayback"));
        Check("compiled legacy damage particles derive motion and clear at replay teardown",Calls(Body(legacy,"Refresh"),"UnityEngine.Transform","get_position")&&Calls(Body(controller,"Update"),legacy,"Refresh")&&Calls(Body("ReplayMod.Core.ReplayVfxPlayback","ClearOwnedObjects"),legacy,"Clear"));
        Check("compiled independent fire checkpoint state clones and clears",Calls(Body(seek,"Add"),flameState,"Add")&&Calls(Body(seek,"CopyTo"),flameState,"CopyTo")&&Calls(Body(seek,"Clone"),flameState,"CloneTo")&&Calls(Body(seek,"Clear"),flameState,"Clear"));
        var refresh=Body(controller,"RefreshFuelFlames");
        bool exactOwnerReference=Calls(refresh,"System.Object","ReferenceEquals")||refresh?.Body.Instructions.Any(instruction=>
            instruction.OpCode.Code==Mono.Cecil.Cil.Code.Ldfld&&instruction.Operand is FieldReference field&&field.DeclaringType.FullName=="ReplayMod.Core.UnitController/PlayedFuelFlame"&&field.Name=="owner"&&
            instruction.Next?.OpCode.Code is Mono.Cecil.Cil.Code.Bne_Un or Mono.Cecil.Cil.Code.Bne_Un_S)==true;
        Check("compiled fire attachment captures exact actor instance and detaches checkpoint owner lifetimes",Read(Body(controller,"Execute",flameEvent),"ReplayMod.Core.UnitController/PlayedFuelFlame","owner")&&exactOwnerReference&&Calls(Body(seek,"Forget"),flameState,"DetachOwner"));
        Check("compiled fire cut rebasing and playback teardown preserve explicit lifetimes",Calls(Body("ReplayMod.Core.RollingReplayBuffer","Snapshot"),flameEvent,"RebaseTime")&&Calls(Body(controller,"ReleaseOwnedPresentationObjects"),controller,"ClearFuelFlames")&&Calls(Body(fire,"Dispose"),"UnityEngine.GameObject","SetActive")&&Calls(Body(fire,"Dispose"),"UnityEngine.Object","Destroy"));
        Console.WriteLine($"Aircraft lighting/fire API/integration audit: {checks} groups, {failures} failures");return(checks,failures);
    }
    private static IEnumerable<TypeDefinition> AllTypes(IEnumerable<TypeDefinition> roots){foreach(var root in roots){yield return root;foreach(var child in AllTypes(root.NestedTypes))yield return child;}}
}
